def display_sample_count(traces: List[CallTrace], stderr: IO[str]) ->None:
    func_counts: collections.Counter = collections.Counter()
    for trace in traces:
        func_counts[trace.func] += 1
    for func, count in func_counts.items():
        qualname = f"{func.__module__}.{func.__qualname__}"
        print(f"Annotation for {qualname} based on {count} call trace(s).", file=stderr)
